import sys
import heapq

def find(parent, x):
    if parent[x] != x:
        parent[x] = find(parent, parent[x])
    return parent[x]

def union(parent, rank, x, y):
    rootX = find(parent, x)
    rootY = find(parent, y)
    if rootX != rootY:
        if rank[rootX] > rank[rootY]:
            parent[rootY] = rootX
        elif rank[rootX] < rank[rootY]:
            parent[rootX] = rootY
        else:
            parent[rootY] = rootX
            rank[rootX] += 1

def kruskal(n, edges, skip_edge):
    parent = list(range(n + 1))
    rank = [0] * (n + 1)
    mst_weight = 0
    mst_edges = []
    for weight, u, v in edges:
        if (u, v) == skip_edge or (v, u) == skip_edge:
            continue
        if find(parent, u) != find(parent, v):
            union(parent, rank, u, v)
            mst_weight += weight
            mst_edges.append((weight, u, v))
    return mst_weight, mst_edges

def second_mst(n, edges, first_edge):
    original_weight, _ = kruskal(n, edges, None)
    max_energy = -1
